 */
export interface AgentThought extends BaseConcreteNode {
  readonly type: NodeType.AGENT_THOUGHT;
  readonly role: 'model';
}

export interface ToolExecution extends BaseConcreteNode {
  readonly type: NodeType.TOOL_EXECUTION;
}

