import type { ConcreteNode } from '../graph/types.js';

/**
 * Options controlling how a list of nodes is rendered into an LLM-readable
 * transcript.
 */
export interface FormatNodesForLlmOptions {
  /**
   * The maximum number of characters a single tool response payload may
   * occupy in the transcript. Responses exceeding this are truncated in the
   * middle, preserving a prefix and a suffix. Defaults to 2000.
   */
  maxToolResponseChars?: number;
}

const DEFAULT_MAX_TOOL_RESPONSE_CHARS = 2000;

/**
 * Truncates a string that exceeds `max` characters by keeping a prefix and a
 * suffix and collapsing the middle into a marker describing how many
 * characters were dropped.
 */
function truncateMiddle(text: string, max: number): string {
  if (max <= 0 || text.length <= max) {
    return text;
  }
  const prefixLen = Math.floor(max / 2);
  const suffixLen = max - prefixLen;
  const removed = text.length - prefixLen - suffixLen;
  const prefix = text.slice(0, prefixLen);
  const suffix = text.slice(text.length - suffixLen);
  return `${prefix}... [TRUNCATED ${removed} chars] ...${suffix}`;
}

/**
 * Renders a list of {@link ConcreteNode}s into a compact, LLM-readable
 * transcript.
 *
 * Each node becomes a single line of the form:
 *   `[Turn N] [ROLE] [TYPE]: content`
 *
 * where `N` is a 1-based turn counter (nodes sharing a `turnId` share a turn
 * number), `ROLE` is the upper-cased node role (defaulting to `SYSTEM` when the
 * role is undefined), and `TYPE` is the node type.
 *
 * The content is derived from the node's payload:
 *   - text payloads use the text verbatim,
 *   - function calls render as `CALL: name({args})`,
 *   - function responses render as `[SEMANTIC_WRAPPER (toolName)]: {json}` and
 *     are truncated when they exceed `maxToolResponseChars`.
 */
export function formatNodesForLlm(
  nodes: readonly ConcreteNode[],
  options: FormatNodesForLlmOptions = {},
): string {
  const maxToolResponseChars =
    options.maxToolResponseChars ?? DEFAULT_MAX_TOOL_RESPONSE_CHARS;

  const turnNumbers = new Map<string, number>();
  let nextTurnNumber = 1;

  let transcript = '';
  for (const node of nodes) {
    const turnKey = node.turnId;
    let turnNumber: number;
    if (turnKey !== undefined && turnNumbers.has(turnKey)) {
      turnNumber = turnNumbers.get(turnKey)!;
    } else {
      turnNumber = nextTurnNumber++;
      if (turnKey !== undefined) {
        turnNumbers.set(turnKey, turnNumber);
      }
    }

    const role = node.role ? String(node.role).toUpperCase() : 'SYSTEM';

    const payload = node.payload;
    let nodeContent = '';
    if (payload.text) {
      nodeContent = payload.text;
    } else if (payload.functionCall) {
      nodeContent = `CALL: ${payload.functionCall.name}(${JSON.stringify(
        payload.functionCall.args,
      )})`;
    } else if (payload.functionResponse) {
      const toolName = payload.functionResponse.name;
      const responseJson = JSON.stringify(payload.functionResponse.response);
      const truncated = truncateMiddle(responseJson, maxToolResponseChars);
      nodeContent = `[SEMANTIC_WRAPPER (${toolName})]: ${truncated}`;
    }

    transcript += `[Turn ${turnNumber}] [${role}] [${node.type}]: ${nodeContent}\n`;
  }

  return transcript;
}
