/**
 * A structured, machine-readable snapshot of the conversation's context.
 *
 * Instead of a single free-form text summary, the master state is broken into
 * distinct, incrementally-updatable lists so that individual pieces of context
 * can be added, refreshed, or evicted independently.
 */
export interface SnapshotState {
  /** Outstanding goals / work items the agent is actively pursuing. */
  active_tasks: string[];
  /** Durable factual knowledge discovered during the conversation. */
  discovered_facts: string[];
  /** User-stated constraints, preferences, and standing instructions. */
  constraints_and_preferences: string[];
  /** A rolling summary of the most recent events, oldest first. */
  recent_arc: string[];
}

/**
 * A patch emitted by the LLM describing how the master state should change.
 * Each list field contains new items to append; `deletions` lists items that
 * should be removed (e.g. tasks that have since completed).
 */
interface SnapshotPatch {
  active_tasks?: string[];
  discovered_facts?: string[];
  constraints_and_preferences?: string[];
  recent_arc?: string[];
  deletions?: string[];
}

/** Information about the most recent usable snapshot baseline. */
export interface BaselineSnapshotInfo {
  /** The snapshot node that was found. */
  node: ConcreteNode;
  /** The snapshot's serialized state text. */
  text: string;
  /** The index of the node within the scanned list. */
  index: number;
}

const DEFAULT_MAX_SUMMARY_TURNS = 5;
const DEFAULT_MAX_STATE_TOKENS = 4000;

/**
 * The order in which categories are evicted when the state exceeds its token
 * budget. Earlier entries are dropped first (least critical to retain), so
 * user constraints/preferences are the last thing to be evicted.
 */
const STATE_LIST_KEYS: Array<keyof SnapshotState> = [
  'active_tasks',
  'discovered_facts',
  'constraints_and_preferences',
  'recent_arc',
];

const EVICTION_PRIORITY: Array<keyof SnapshotState> = [
  'recent_arc',
  'discovered_facts',
  'active_tasks',
  'constraints_and_preferences',
];

const SNAPSHOT_STATE_SCHEMA: Record<string, unknown> = {
  type: 'object',
  properties: {
    active_tasks: { type: 'array', items: { type: 'string' } },
    discovered_facts: { type: 'array', items: { type: 'string' } },
    constraints_and_preferences: { type: 'array', items: { type: 'string' } },
    recent_arc: { type: 'array', items: { type: 'string' } },
    deletions: { type: 'array', items: { type: 'string' } },
  },
};

function createEmptyState(): SnapshotState {
  return {
    active_tasks: [],
    discovered_facts: [],
    constraints_and_preferences: [],
    recent_arc: [],
  };
}

function asStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value.filter((item): item is string => typeof item === 'string');
}

/** Coerces an arbitrary parsed object into a well-formed {@link SnapshotState}. */
function normalizeState(value: unknown): SnapshotState {
  const state = createEmptyState();
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return state;
  }
  const record = value as Record<string, unknown>;
  for (const key of STATE_LIST_KEYS) {
    state[key] = asStringArray(record[key]);
