  text: string;
  /** The index of the node within the scanned list. */
  index: number;
}

const DEFAULT_MAX_SUMMARY_TURNS = 5;
const DEFAULT_MAX_STATE_TOKENS = 4000;

/**
 * The order in which categories are evicted when the state exceeds its token
 * budget. Earlier entries are dropped first (least critical to retain), so
 * user constraints/preferences are the last thing to be evicted.
